def seed(apps, schema_editor):
    Author = apps.get_model("catalog", "Author")
    Genre = apps.get_model("catalog", "Genre")
    Book = apps.get_model("catalog", "Book")

    genre_names = sorted({book[2] for _, _, books in SEED for book in books})
    genres = {name: Genre.objects.get_or_create(name=name)[0] for name in genre_names}
    new_books = []
    for name, sort_name, books in SEED:
        author, _ = Author.objects.get_or_create(
            name=name, defaults={"sort_name": sort_name}
        )
        for title, year, genre, description in books:
            new_books.append(
                Book(
                    title=title,
                    author=author,
                    genre=genres[genre],
                    publication_year=year,
                    description=description,
                )
            )
    Book.objects.bulk_create(new_books)


def unseed(apps, schema_editor):
    Author = apps.get_model("catalog", "Author")
    Genre = apps.get_model("catalog", "Genre")
    Book = apps.get_model("catalog", "Book")

    for name, _, books in SEED:
        titles = [book[0] for book in books]
        Book.objects.filter(author__name=name, title__in=titles).delete()

